// Character-local equipment storage. Moving an item preserves the complete object.
const STASH_LIMIT=100;
function stashItems(){return p.stash||(p.stash=[])}
function stashTransfer(fromStash,index){if(!started||dead||!Number.isInteger(index)||index<0)return false;let storage=stashItems(),source=fromStash?storage:p.bag,target=fromStash?p.bag:storage,limit=fromStash?20:STASH_LIMIT;
 if(!source[index])return false;if(target.length>=limit){say(fromStash?'鞄が満杯です。先に装備を預けてください':'倉庫が満杯です');return false}
 let item=source.splice(index,1)[0];target.push(item);
 if(save()===false){target.pop();source.splice(index,0,item);say('保存できなかったため、移動を取り消しました');return false}
 panel('stash');let side=fromStash?'storage':'bag',buttons=Array.from($('card').querySelectorAll('[data-stash-side="'+side+'"]')),focus=buttons[Math.min(index,buttons.length-1)]||$('card').querySelector('[data-stash-side]');if(focus){focus.focus({preventScroll:true});menuReveal(focus)}say(fromStash?'鞄へ取り出しました':'倉庫へ預けました');return true;
}
function stashList(items,stored){return items.length?items.map((it,i)=>'<div role="button" tabindex="0" class="stash-item" data-stash-side="'+(stored?'storage':'bag')+'" onclick="stashTransfer('+stored+','+i+')" '+((stored?p.bag.length>=20:stashItems().length>=STASH_LIMIT)?'disabled':'')+'><small>'+EQUIPMENT[it.slot].label+(it.locked?' · 売却保護中':'')+'</small>'+itemDetails(it)+'<span class="stash-gems">'+(it.sockets||[]).filter(s=>s.gem).map(s=>GEM[s.gem.type].name+' Lv'+s.gem.level).join(' / ')+'</span><b>'+(stored?'鞄へ取り出す →':'← 倉庫へ預ける')+'</b></div>').join(''):'<p class="muted">'+(stored?'倉庫は空です。残したい装備を鞄から預けられます。':'鞄は空です。')+'</p>'}
function showStash(){let storage=stashItems();$('card').classList.add('wide');$('card').innerHTML='<button class="close" onclick="closePanel()">閉じる ×</button><label>ASHEN DEPTHS / EQUIPMENT STORAGE</label><nav class="tabs"><button onclick="panel(\'inventory\')">装備・鍛造</button><button onclick="panel(\'gems\')">スキルジェム</button><button onclick="panel(\'skills\')">パッシブツリー</button><button onclick="panel(\'stash\')">倉庫</button></nav><h2>遺物の倉庫</h2><p>装備を選んでAで移動。ジェム・リンク・売却保護はそのまま保持します。倉庫内の装備やジェムは能力に影響せず、経験値も入りません。</p><p class="muted">キャラクター専用の倉庫です。セーブ・バックアップ・JSON書き出しに含まれます。</p><div class="stash-columns"><section><h3>倉庫 '+storage.length+' / '+STASH_LIMIT+'</h3>'+stashList(storage,true)+'</section><section><h3>鞄 '+p.bag.length+' / 20</h3>'+stashList(p.bag,false)+'</section></div>';frameMenu('stash');let first=$('card').querySelector('.stash-item:not(:disabled)');first?.focus({preventScroll:true})}
const stashPanelBase=panel;panel=kind=>{if(kind!=='stash'){stashPanelBase(kind);return}if(!started||dead)return;stashPanelBase('pause');inventoryNav.open=false;tutorialGuideOpen=false;padSettingsOpen=false;showStash()};
